		if (renderPassMaterial) mesh.setMaterialForRenderPass(renderPassId, renderPassMaterial);
		const ret = mesh.render(subMesh, enableAlphaMode, effectiveMeshReplacement);
		this._hasRenderedOnce = true;
		if (renderPassMaterial) mesh.setMaterialForRenderPass(renderPassId, void 0);
		if (this.onAfterRenderObservable) this.onAfterRenderObservable.notifyObservers(this);
		return ret;
